class Solution:
    def getWordsInLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        n = len(words)
        if n == 0:
            return []
        lengths = [len(word) for word in words]
        dp = [(1, -1) for _ in range(n)]
        max_len = 1
        best_idx = 0

        for i in range(n):
            for j in range(i):
                if groups[i] != groups[j] and lengths[i] == lengths[j]:
                    s = words[j]
                    t = words[i]
                    diff = 0
                    for a, b in zip(s, t):
                        if a != b:
                            diff += 1
                            if diff > 1:
                                break
                    if diff == 1:
                        if dp[j][0] + 1 > dp[i][0]:
                            dp[i] = (dp[j][0] + 1, j)
            if dp[i][0] > max_len:
                max_len = dp[i][0]
                best_idx = i

        path = []
        current = best_idx
        while current != -1:
            path.append(current)
            current = dp[current][1]
        path = path[::-1]
        return [words[i] for i in path]

class Solution:
    def findIndices(
        self, nums: List[int], indexDifference: int, valueDifference: int
    ) -> List[int]:
        mi = mx = 0
        for i in range(indexDifference, len(nums)):
            j = i - indexDifference
            if nums[j] < nums[mi]:
                mi = j
            if nums[j] > nums[mx]:
                mx = j
            if nums[i] - nums[mi] >= valueDifference:
                return [mi, i]
            if nums[mx] - nums[i] >= valueDifference:
                return [mx, i]
        return [-1, -1]

class Solution:
    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)
        ans = ""
        for i in range(n):
            for j in range(i + k, n + 1):
                t = s[i:j]
                if t.count("1") == k and (
                    not ans or j - i < len(ans) or (j - i == len(ans) and t < ans)
                ):
                    ans = t
        return ans

